WITH ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY city ORDER BY rating NULLS LAST, id) AS latest_rank FROM suppliers QUALIFY latest_rank = 1), metrics AS (SELECT *, SUM(rating) OVER (PARTITION BY city ORDER BY latest_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_rating, LAG(rating, 2) OVER (ORDER BY rating, id) prev_rating, ROW_NUMBER() OVER (PARTITION BY country ORDER BY latest_rank, id) event_seq FROM ranked), eligible AS (SELECT s.* FROM metrics s WHERE EXISTS (SELECT 1 FROM products c WHERE c.supplier_id = s.id AND c.price > 380)), ranked_suppliers AS (SELECT id, country, city, rating, latest_rank, running_rating, event_seq FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY country, city ORDER BY event_seq DESC, id) AS rank_in_group FROM eligible) t WHERE rank_in_group = 1) SELECT id, country, rating, latest_rank, running_rating, event_seq FROM ranked_suppliers ORDER BY event_seq;
